import React from 'react';

const Footer = () => {
    return (
        <footer className="footer">
            <div className="container">
                <p>🇨🇷 <strong>Recordar para Defender la Democracia</strong></p>
                <p>Campaña educativa sobre la dictadura de los hermanos Tinoco en Costa Rica</p>
                <p className="copy">© 2026 - Proyecto Educativo</p>
            </div>
        </footer>
    );
};

export default Footer;
